/** Events */
export const events = {
	analysisReady: makeEvent<AnalysisReadyEvent, AnalysisReadyEvent>("analysis-ready"),
	audioDeviceChanged: makeEvent<AudioDeviceChangedEvent, AudioDeviceChangedEvent>("audio-device-changed"),
	cuesChanged: makeEvent<CuesChangedEvent, CuesChangedEvent>("cues-changed"),
	engineEvent: makeEvent<EngineEventEvent, EngineEventEvent>("engine-event"),
	engineTelemetry: makeEvent<EngineTelemetryEvent, EngineTelemetryEvent>("engine-telemetry"),
	fxStateChanged: makeEvent<FxStateChangedEvent, FxStateChangedEvent>("fx-state-changed"),
	hotCuesChanged: makeEvent<HotCuesChangedEvent, HotCuesChangedEvent>("hot-cues-changed"),
	importProgress: makeEvent<ImportProgressEvent, ImportProgressEvent>("import-progress"),
	libraryChanged: makeEvent<LibraryChangedEvent, LibraryChangedEvent>("library-changed"),
	trackLoadFailed: makeEvent<TrackLoadFailedEvent, TrackLoadFailedEvent>("track-load-failed"),
	trackLoaded: makeEvent<TrackLoadedEvent, TrackLoadedEvent>("track-loaded"),
};

/* Types */
/**  Which results an analyzer produces or a job requests. */
export type AnalysisFeatures = {
	/**  BPM and beat grid. */
	tempo: boolean,
	/**  Musical key. */
	key: boolean,
	/**  EBU R128 loudness and true peak. */
	loudness: boolean,
	/**  Waveform peaks. */
	peaks: boolean,
};

/**  Analysis of a track was stored (BPM, key and grid are readable). */
export type AnalysisReadyEvent = TrackId;

/**  Analysis state of a track. */
export type AnalysisStatusDto = 
/**  Not analysed yet. */
"pending" | 
/**  A worker is analysing it. */
"running" | 
/**  Analysis stored. */
"done" | 
/**  Decoding or analysis failed. */
"failed" | 
/**  Analysed by an older analyzer version. */
"stale";

/**  Static information about the running build. */
export type AppInfo = {
	/**  Product name. */
	name: string,
	/**  Workspace version. */
	version: string,
	/**  Tauri runtime version. */
	tauri_version: string,
	/**  Target OS (`windows`, `macos`, `linux`). */
	os: string,
	/**  Target architecture (`x86_64`, `aarch64`). */
	arch: string,
	/**  Decks the engine architecture supports. */
	max_decks: number,
	/**  Decks the MVP UI shows. */
	visible_decks: number,
};

/**
 *  Raw artwork bytes. On the wire this is a binary payload (an `ArrayBuffer`
 *  in the webview), not JSON; the generated binding types it as `number[]`, so
 *  callers read it with `new Uint8Array(buffer as unknown as ArrayBuffer)`.
 */
export type ArtworkBytes = number[];

/**  The audio stream was (re)started or stopped. */
export type AudioDeviceChangedEvent = AudioStatus;

/**  An output device and what it supports, for the settings screen. */
export type AudioDeviceInfo = {
	/**  Name as the host reports it; used to select the device. */
	name: string,
	/**  The host's default output device. */
	is_default: boolean,
	/**  Most output channels any configuration offers. */
	max_channels: number,
	/**  Default sample rate in Hz. */
	default_sample_rate: number | null,
	/**  Supported sample rate ranges `[min, max]` in Hz. */
	sample_rate_ranges: ([number, number])[],
	/**  Supported buffer size range `[min, max]` in frames, when known. */
	buffer_frames: [number, number] | null,
};

/**  One audio host as reported to the settings screen. */
export type AudioHostInfo = {
	/**  Host API. */
	kind: AudioHostKind,
	/**  Display name. */
	name: string,
	/**  Compiled in and usable on this machine. */
	available: boolean,
	/**  The platform default host. */
	is_default: boolean,
};

/**  Audio host API. */
export type AudioHostKind = 
/**  Windows WASAPI (default on Windows). */
"wasapi" | 
/**  Steinberg ASIO (Windows, only in builds with the `asio` feature). */
"asio" | 
/**  macOS Core Audio. */
"core_audio" | 
/**  Linux ALSA. */
"alsa" | 
/**  JACK (Linux/macOS, only in builds with the `jack` feature). */
"jack";

/**
 *  Persisted audio output settings (`settings` table, key `audio`).
 * 
 *  Default routing is one multichannel device: master on channels 1/2 and
 *  headphones on 3/4, as on the DDJ-FLX4 (ADR 0001, deviation 5).
 */
export type AudioSettings = {
	/**  Host API, `None` for the platform default. */
	host: AudioHostKind | null,
	/**  Output device name as reported by the host, `None` for the default device. */
	device: string | null,
	/**  Requested sample rate in Hz, `None` for the device default. */
	sample_rate: number | null,
	/**  Requested buffer size in frames, `None` for the device default. */
	buffer_frames: number | null,
	/**  Master output channels. */
	master: ChannelPair,
	/**  Headphone output channels, `None` to disable headphone output. */
	headphones: ChannelPair | null,
};

/**  State of the audio output, for the top bar and the settings screen. */
export type AudioStatus = {
	/**  A stream is open and the engine is rendering. */
	running: boolean,
	/**  `"device"` or `"offline"` (no device, used by tests). */
	backend: string,
	/**  Host API name. */
	host: string | null,
	/**  Device name. */
	device: string | null,
	/**  Engine sample rate in Hz. */
	sample_rate: number | null,
	/**  Device channel count. */
	channels: number | null,
	/**  Requested buffer size in frames; `None` is the device default. */
	buffer_frames: number | null,
	/**  Output buffer latency in milliseconds, known only for a fixed buffer. */
	latency_ms: number | null,
	/**  Master pair in use. */
	master: ChannelPair | null,
	/**  Headphone pair in use. */
	headphones: ChannelPair | null,
	/**  The device could not carry the requested routing; stereo is used. */
	stereo_fallback: boolean,
	/**  Why the engine is not running, if it is not. */
	error: string | null,
};

/**  A Beat FX unit. */
export type BeatFxUnitDto = {
	/**  Channel assignment. */
	assign: FxAssign,
	/**  Multi or Single. */
	mode: FxMode,
	/**  `FX_CHAIN_SLOTS` slots. Single mode uses slot 0 only. */
	slots: FxSlotDto[],
	/**  ON/OFF. */
	on: boolean,
	/**  BPM Auto or Tap. */
	bpm_source: FxBpmSource,
	/**  Last tapped tempo. */
	tap_bpm: number | null,
	/**  Effect played by Release FX. */
	release_effect: EffectKey | null,
	/**  How long the release effect runs, milliseconds. */
	release_hold_ms: number,
};

/**
 *  A constant-tempo beat grid. RT-safe.
 * 
 *  Invariants (checked by [`BeatGrid::new`]): `bpm` is finite and `> 0`,
 *  `anchor` is finite, `beats_per_bar >= 1`. `anchor` is the time of a
 *  downbeat (beat 1 of a bar) in seconds from the first decoded frame; it may
 *  be negative when the first downbeat precedes the audio. Beat `n` falls at
 *  `anchor + n * 60 / bpm`.
 */
export type BeatGrid = BeatGridRaw;

/**  Unvalidated wire form of [`BeatGrid`]; deserialization validates it. */
export type BeatGridRaw = {
	/**  Time of beat 0 (a downbeat), seconds. */
	anchor: Seconds,
	/**  Tempo at original speed. */
	bpm: Bpm,
	/**  Beats per bar. */
	beats_per_bar: number,
};

/**
 *  A musical length or position in beats (quarter notes in 4/4), `f64`.
 * 
 *  Signed: negative values mean backwards (beat jump) or before the grid
 *  anchor. Loop and effect lengths are positive.
 */
export type Beats = number | null;

/**  Tempo in beats per minute. Valid values are finite and `> 0`. */
export type Bpm = number | null;

/**  Sound Color FX of one channel. */
export type CfxDto = {
	/**  CFX type (one of `FxStateDto::cfx_kinds`). */
	kind: EffectKey,
	/**  Knob position `[-1, 1]`, 0 is neutral. */
	amount: number | null,
};

/**  A pair of output channels (zero-based) on the output device. */
export type ChannelPair = {
	/**  Left channel index. */
	left: number,
	/**  Right channel index. */
	right: number,
};

/**
 *  Snapshot of one channel strip, for the UI and session restore. Not sent
 *  to the audio thread as a whole: every field has its own `EngineCommand`.
 */
export type ChannelState = {
	/**  Deck feeding this channel. */
	deck: DeckId,
	/**  Input trim, linear. */
	trim: Gain,
	/**  EQ gains indexed by [`EqBand::index`], linear, `0..=db_to_gain(EQ_MAX_GAIN_DB)`. */
	eq: [Gain, Gain, Gain],
	/**  Filter amount in `[-1, 1]`: negative = low-pass, positive = high-pass, 0 = off. */
	filter: number | null,
	/**  Channel fader position in `[0, 1]`; the engine applies the fader curve. */
	fader: number | null,
	/**  Headphone cue (PFL) on. */
	pfl: boolean,
	/**  Crossfader side. */
	crossfader_assign: CrossfaderAssign,
};

/**  Error returned by commands. Serialized as a tagged union for the UI. */
export type CommandError = 
/**  Internal state could not be accessed (poisoned lock, settings file). */
{ kind: "internal"; message: string } | 
/**  The audio engine is stopped or a device call failed. */
{ kind: "audio"; message: string } | 
/**  A file could not be read or decoded, or is too long. */
{ kind: "media"; message: string } | 
/**  An argument is out of range, or the deck has no track for the action. */
{ kind: "invalid"; message: string };

/**  Which crossfader side a channel is assigned to. */
export type CrossfaderAssign = 
/**  Left side (A). */
"a" | 
/**  Bypasses the crossfader. */
"thru" | 
/**  Right side (B). */
"b";

/**  Crossfader curve. Gains are computed by [`CrossfaderCurve::gains`]. */
export type CrossfaderCurve = 
/**
 *  Constant power: `a = cos(x * pi/2)`, `b = sin(x * pi/2)`. Both sides at
 *  -3 dB in the centre, no perceived volume dip. Default for blending.
 */
"constant_power" | 
/**  Linear: `a = 1 - x`, `b = x`. Both sides at -6 dB in the centre (dip). */
"linear" | 
/**
 *  Scratch cut: each side stays at unity and cuts over the last
 *  [`SHARP_CUT_WIDTH`] of travel at the opposite edge.
 */
"sharp";

/**
 *  A stored cue: hot cue, memory cue or saved loop.
 * 
 *  Invariants: `start` is finite and `>= 0`; when `end` is `Some`, `start <
 *  end`; `kind == Loop` requires `end`. At most one hot cue per
 *  `(track, index)`. Not RT: owns a `String`.
 */
export type Cue = {
	/**  Row id, `None` before the cue is persisted. */
	id: CueId | null,
	/**  Hot, memory or loop. */
	kind: CueKind,
	/**  Cue point or loop in, seconds. */
	start: Seconds,
	/**  Loop out, seconds, if this cue is a loop. */
	end: Seconds | null,
	/**  Display colour, `None` for the theme default. */
	color: CueColor | null,
	/**  User label, may be empty. */
	name: string,
};

/**
 *  A display colour, 8-bit sRGB. Mapping to a controller's LED palette is the
 *  MIDI layer's job.
 */
export type CueColor = {
	/**  Red, 0..=255. */
	r: number,
	/**  Green, 0..=255. */
	g: number,
	/**  Blue, 0..=255. */
	b: number,
};

/**  A hot cue, memory cue or saved loop (`cues.id`). */
export type CueId = number;

/**  What a stored cue is (`cues.kind` column). */
export type CueKind = 
/**  Hot cue on a pad. May be a hot loop when the cue has an `end`. */
{ kind: "hot"; 
/**  Pad slot. */
index: HotCueIndex } | 
/**  Memory cue, recalled with CUE/LOOP CALL. May be a loop when it has an `end`. */
{ kind: "memory" } | 
/**  Saved loop without a pad assignment. */
{ kind: "loop" };

/**  The stored cues of a track changed. */
export type CuesChangedEvent = TrackId;

/**
 *  A deck index, `0..MAX_DECKS`. Deck 1 in the UI is `DeckId(0)`.
 * 
 *  Invariant: the inner index is always `< MAX_DECKS`. The field is private
 *  and deserialization goes through [`DeckId::new`], so engine code may index
 *  `[T; MAX_DECKS]` arrays with [`DeckId::index`] without a bounds check
 *  failing. RT-safe.
 */
export type DeckId = number;

/**
 *  Snapshot of one deck's control state. Not RT (owns no heap today, but is
 *  not part of the RT contract and may grow).
 */
export type DeckState = {
	/**  Which deck. */
	deck: DeckId,
	/**  Loaded track, if any. */
	track: TrackId | null,
	/**  Transport state. */
	play_state: PlayState,
	/**  Main cue point. */
	cue_point: Seconds | null,
	/**  Track tempo at original speed, from analysis. */
	track_bpm: Bpm | null,
	/**  Track key, from analysis. */
	track_key: MusicalKey | null,
	/**  Beat grid, from analysis. */
	beat_grid: BeatGrid | null,
	/**  Tempo fader range. */
	tempo_range: TempoRange,
	/**  Tempo fader position in `[-1, 1]` (`+1` = fastest). */
	tempo_fader: number | null,
	/**  Key lock (master tempo): tempo changes keep pitch. */
	key_lock: boolean,
	/**  Key shift in semitones applied on top of the track key. */
	key_shift: number,
	/**  Sync mode. */
	sync: SyncMode,
	/**  True if this deck is the sync leader (election: `EngineCommand::SetLeader`). */
	is_leader: boolean,
	/**  Slip mode on. */
	slip: boolean,
	/**
	 *  Quantize on: cue, hot cue and loop points snap to the nearest beat, a
	 *  hot cue jump waits for the next beat. See `EngineCommand::SetQuantize`.
	 */
	quantize: boolean,
	/**  Jog in vinyl mode: platter touch scratches. Otherwise it bends pitch. */
	vinyl_mode: boolean,
	/**  Active loop, if looping. */
	active_loop: LoopRegion | null,
	/**  Pad mode shown by the pads and the middle UI panel. */
	pad_mode: PadMode,
};

/**  Per-deck fast-moving state. RT-safe. */
export type DeckTelemetry = {
	/**  A track buffer is loaded. */
	loaded: boolean,
	/**  Transport is running (including cue preview and loop roll). */
	playing: boolean,
	/**  Playhead in engine frames. */
	position: Frames,
	/**  Track length in engine frames. */
	duration: Frames,
	/**  Where playback would be without slip mode, when slip is engaged. */
	slip_position: Frames | null,
	/**  Current playback rate (tempo fader, sync, bend and scratch combined). */
	rate: number | null,
	/**
	 *  Effective tempo (grid BPM times rate, sync included), if the track
	 *  has a grid.
	 */
	bpm: Bpm | null,
	/**  Position inside the current beat, `[0, 1)`; 0 when there is no grid. */
	beat_phase: number | null,
	/**  Zero-based beat within the bar; 0 when there is no grid. */
	beat_in_bar: number,
	/**  Sync mode the engine applies to this deck. */
	sync_mode: SyncMode,
	/**
	 *  This deck is the sync leader: `EngineTelemetry::leader` names it.
	 *  A leader can have sync off.
	 */
	is_leader: boolean,
	/**
	 *  Current loop in engine frames: the playing one, or the last one that
	 *  `LoopToggle` re-enters. Cleared on track load.
	 */
	loop_region: FrameRegion | null,
	/**  The playhead is looping inside `loop_region` (loop, hot loop or roll). */
	loop_active: boolean,
	/**  Post-fader channel level. */
	meter: StereoMeter,
};

/**  A directory listing for the file explorer pane. */
export type DirListing = {
	/**  Listed folder; empty for the list of roots. */
	path: string,
	/**  Parent folder, `None` at a root. */
	parent: string | null,
	/**  Folders first, then files, each sorted by name. */
	entries: FsEntry[],
};

/**
 *  Globally unique effect type: provider plus the provider's effect id.
 *  Persisted in presets as `"provider:id"`-like pairs; both parts are stable.
 */
export type EffectKey = {
	/**  Factory provider id (`"builtin"`, later `"clap"`, `"vst3"`). */
	provider: string,
	/**  Effect id inside the provider (built-ins: snake_case name; plugins: plugin id). */
	id: string,
};

/**  A discrete notification from the audio thread. RT-safe. */
export type EngineEvent = 
/**  A hot cue was stored from the playhead; app-core persists it. */
{ type: "hot_cue_set"; 
/**  Deck. */
deck: DeckId; 
/**  Pad slot. */
index: HotCueIndex; 
/**  Stored region (a hot loop if `end` is set). */
cue: FrameRegion } | 
/**  The main cue point moved (CUE pressed while paused). */
{ type: "cue_point_set"; 
/**  Deck. */
deck: DeckId; 
/**  New cue point. */
position: Frames } | 
/**  A loop was set by loop in/out or auto loop; app-core may save it. */
{ type: "loop_set"; 
/**  Deck. */
deck: DeckId; 
/**  Loop region. */
region: FrameRegion } | 
/**  Playback reached the end of the track and stopped. */
{ type: "track_ended"; 
/**  Deck. */
deck: DeckId } | 
/**
 *  The output device went away. The stream is dead; the control thread
 *  opens a new one. Reported by the device layer, not the render path.
 */
{ type: "device_lost" } | 
/**  The host moved the stream to another device and keeps playing. */
{ type: "device_changed" } | 
/**  The backend reported some other stream error. */
{ type: "stream_error" };

/**  A discrete engine or device notification (track ended, device lost). */
export type EngineEventEvent = EngineEvent;

/**  Full engine snapshot. RT-safe: `Copy`, fixed size, written without allocation. */
export type EngineTelemetry = {
	/**  Increments by one per published snapshot; lets readers detect gaps. */
	sequence: number,
	/**  Frames rendered since the stream started (engine clock). */
	engine_time: Frames,
	/**  Engine sample rate; converts every `Frames` here to seconds. */
	sample_rate: SampleRate,
	/**  One entry per deck, indexed by [`DeckId::index`]. */
	decks: [DeckTelemetry, DeckTelemetry, DeckTelemetry, DeckTelemetry],
	/**  Master output level. */
	master: StereoMeter,
	/**  Headphone output level. */
	headphones: StereoMeter,
	/**  Deck FX units (insert chains), indexed by [`DeckId::index`]. */
	fx_decks: [FxUnitTelemetry, FxUnitTelemetry, FxUnitTelemetry, FxUnitTelemetry],
	/**  Master FX unit. */
	fx_master: FxUnitTelemetry,
	/**  Send FX units, indexed by bus. */
	fx_sends: [FxUnitTelemetry, FxUnitTelemetry],
	/**  Current sync leader. See `EngineCommand::SetLeader` for the election. */
	leader: DeckId | null,
	/**  Callback time divided by block duration, smoothed, `0..` (1.0 = overrun). */
	dsp_load: number | null,
	/**  Buffer underruns reported by the backend since the stream started. */
	xruns: number,
	/**  `EngineEvent`s dropped because their ring was full. */
	dropped_events: number,
};

/**  Engine snapshot pushed to the UI at ~60 Hz (ADR 0003, ADR 0004). */
export type EngineTelemetryEvent = EngineTelemetry;

/**  One band of the 3-band channel EQ. */
export type EqBand = 
/**  Low band. */
"low" | 
/**  Mid band. */
"mid" | 
/**  High band. */
"high";

/**
 *  An engine-side region in frames at the engine rate. RT-safe.
 * 
 *  `end == None` is a point (cue); `Some(end)` is a loop with `start < end`.
 */
export type FrameRegion = {
	/**  Start (cue point or loop in). */
	start: Frames,
	/**  Loop out (exclusive), or `None` for a point. */
	end: Frames | null,
};

/**
 *  A count or position in sample frames (one frame = one sample per channel).
 * 
 *  Always paired with a [`SampleRate`] stated by the context: engine frames are
 *  at the device rate, file frames at the file rate. Positions are measured
 *  from the first decoded frame of the track and are never negative.
 */
export type Frames = number;

/**  One entry of a directory listing. */
export type FsEntry = {
	/**  File or folder name. */
	name: string,
	/**  Absolute path. */
	path: string,
	/**  Folder, audio file or playlist file. */
	kind: FsEntryKind,
};

/**  Kind of a directory entry in the file explorer. */
export type FsEntryKind = 
/**  A folder. */
"dir" | 
/**  A supported audio file. */
"audio" | 
/**  A playlist or collection file the importers read (`m3u`, `m3u8`, `xml`). */
"playlist";

/**  Channel a Beat FX unit is assigned to (BEAT FX CH SELECT). */
export type FxAssign = 
/**  Not assigned (another unit took the channel). */
"none" | 
/**  Channel 1 (deck A). */
"ch1" | 
/**  Channel 2 (deck B). */
"ch2" | 
/**  Both channels, mirrored (1&2). */
"both";

/**  Tempo source of a Beat FX unit. */
export type FxBpmSource = 
/**  Track BPM. */
"auto" | 
/**  Tapped BPM. */
"tap";

/**  A stored chain: the effects of one unit. */
export type FxChainPresetDto = {
	/**  Unique name. */
	name: string,
	/**  At most `FX_CHAIN_SLOTS` slots. */
	slots: FxChainSlotDto[],
};

/**  One effect of a stored chain. */
export type FxChainSlotDto = {
	/**  Effect. */
	effect: EffectKey,
	/**  Normalized parameters by id. */
	params: ([ParamId, number | null])[],
	/**  Wet/dry. */
	wet: number | null,
	/**  Beat division. */
	division: number | null,
	/**  Slot enabled. */
	enabled: boolean,
};

/**  One effect for the UI: contract info plus catalog flags. */
export type FxEffectDto = {
	/**  Unique key. */
	key: EffectKey,
	/**  Display name. */
	name: string,
	/**  Intended routing. */
	routing: FxRouting,
	/**  Reads the beat division. */
	beat_synced: boolean,
	/**  Output continues after input stops. */
	has_tail: boolean,
	/**  Parameters in display order. */
	params: ParamDescriptor[],
	/**  Parameter the LEVEL/DEPTH control drives. */
	primary: ParamId | null,
	/**  Release-category effect. */
	release: boolean,
	/**  Beat divisions the effect accepts, ascending; empty if not synced. */
	divisions: (number | null)[],
};

/**  Multi or Single mode of a Beat FX unit. */
export type FxMode = 
/**  Up to three effects, one primary parameter each. */
"multi" | 
/**  One effect, every parameter editable. */
"single";

/**  One change to the FX model. */
export type FxOp = 
/**  Assigns a Beat FX unit to channel 1, 2 or 1&2. */
{ kind: "set_assign"; 
/**  Unit. */
unit: number; 
/**  Assignment. */
assign: FxAssign } | 
/**  Multi or Single mode. */
{ kind: "set_mode"; 
/**  Unit. */
unit: number; 
/**  Mode. */
mode: FxMode } | 
/**  Chooses the effect of a slot (`None` empties it). */
{ kind: "set_effect"; 
/**  Slot. */
slot: FxSlotRef; 
/**  Effect. */
effect: EffectKey | null } | 
/**  Sets one parameter, normalized. */
{ kind: "set_param"; 
/**  Slot. */
slot: FxSlotRef; 
/**  Parameter. */
param: ParamId; 
/**  Normalized value. */
value: number | null } | 
/**  LEVEL/DEPTH: sets the effect's primary parameter, normalized. */
{ kind: "set_level"; 
/**  Slot. */
slot: FxSlotRef; 
/**  Normalized value. */
value: number | null } | 
/**  Wet/dry. */
{ kind: "set_wet"; 
/**  Slot. */
slot: FxSlotRef; 
/**  `[0, 1]`. */
wet: number | null } | 
/**  Beat division of one slot. */
{ kind: "set_division"; 
/**  Slot. */
slot: FxSlotRef; 
/**  Beats. */
beats: number | null } | 
/**
 *  BEAT left (`-1`) or right (`1`): steps every slot of the unit through
 *  its effect's division list.
 */
{ kind: "step_division"; 
/**  Unit. */
unit: FxUnitRef; 
/**  Direction, sign only. */
direction: number } | 
/**  Slot takes part (Beat FX) or is on (send). */
{ kind: "set_slot_enabled"; 
/**  Slot. */
slot: FxSlotRef; 
/**  State. */
on: boolean } | 
/**  ON/OFF of a Beat FX unit. */
{ kind: "set_unit_on"; 
/**  Unit. */
unit: number; 
/**  State. */
on: boolean } | 
/**  Release FX (SHIFT+ON/OFF). */
{ kind: "release"; 
/**  Unit. */
unit: number } | 
/**  BPM Auto or Tap. */
{ kind: "set_bpm_source"; 
/**  Unit. */
unit: number; 
/**  Source. */
source: FxBpmSource } | 
/**  One tap of the tap tempo; switches the unit to Tap. */
{ kind: "tap"; 
/**  Unit. */
unit: number } | 
/**  Release effect and hold time of a unit. */
{ kind: "set_release_effect"; 
/**  Unit. */
unit: number; 
/**  Effect. */
effect: EffectKey | null; 
/**  Hold, milliseconds. */
hold_ms: number } | 
/**  CFX type of a channel. */
{ kind: "set_cfx_kind"; 
/**  Channel deck. */
deck: DeckId; 
/**  Effect (must be in `cfx_kinds`). */
effect: EffectKey } | 
/**  CFX knob. */
{ kind: "set_cfx"; 
/**  Channel deck. */
deck: DeckId; 
/**  `[-1, 1]`. */
amount: number | null } | 
/**  Send level of a channel to a bus. */
{ kind: "set_send_level"; 
/**  Channel deck. */
deck: DeckId; 
/**  Bus. */
bus: number; 
/**  Linear `[0, 1]`. */
level: number | null } | 
/**  Send tap point. */
{ kind: "set_send_tap"; 
/**  Bus. */
bus: number; 
/**  Post-fader when true. */
post_fader: boolean } | 
/**  Loads a stored effect preset into a slot. */
{ kind: "apply_preset"; 
/**  Slot. */
slot: FxSlotRef; 
/**  Preset (effect must match or the slot switches to it). */
preset: FxPreset } | 
/**  Loads a stored chain into a unit. */
{ kind: "apply_chain"; 
/**  Unit. */
unit: FxUnitRef; 
/**  Chain name. */
name: string } | 
/**  Assigns a pad effect. */
{ kind: "set_pad"; 
/**  Index `0..PAD_FX_COUNT`. */
index: number; 
/**  Assignment. */
pad: PadFxAssignDto };

/**
 *  A saved effect setting (`fx_presets` table). Values are normalized, keyed
 *  by [`ParamId`]; ids the effect no longer has are ignored on recall.
 */
export type FxPreset = {
	/**  Effect type. */
	effect: EffectKey,
	/**  Preset name, unique per effect type. */
	name: string,
	/**  Normalized parameter values. */
	params: ([ParamId, number | null])[],
	/**  Wet/dry mix, `[0, 1]`. */
	wet: number | null,
	/**  Beat division, for beat-synced effects. */
	beat_division: Beats,
};

/**  Presets for the browser. */
export type FxPresetsDto = {
	/**  Factory effect presets (read-only). */
	factory: FxPreset[],
	/**  User effect presets (`fx_presets` table). */
	user: FxPreset[],
	/**  User chain presets. */
	chains: FxChainPresetDto[],
};

/**  Where an effect is meant to sit. */
export type FxRouting = 
/**  In series in a channel or master chain. */
"insert" | 
/**  On a send/return bus (reverbs, delays fed by sends). */
"send_return";

/**
 *  One effect slot of a unit. `params` are normalized values in the effect's
 *  descriptor order.
 */
export type FxSlotDto = {
	/**  Effect, `None` for an empty slot. */
	effect: EffectKey | null,
	/**  Normalized parameters, descriptor order. */
	params: (number | null)[],
	/**  Wet/dry `[0, 1]`. */
	wet: number | null,
	/**  Beat division in beats. */
	division: number | null,
	/**  Beat units: slot takes part when the unit is on. Send units: slot on. */
	enabled: boolean,
};

/**  One slot of a [`FxUnitRef`]. */
export type FxSlotRef = {
	/**  Owner. */
	unit: FxUnitRef,
	/**  Position `0..FX_CHAIN_SLOTS`. */
	slot: number,
};

/**  The FX model changed (assignment, effects, parameters, pads). */
export type FxStateChangedEvent = FxStateDto;

/**  Everything the UI shows of the FX model. */
export type FxStateDto = {
	/**  `BEAT_FX_UNITS` Beat FX units. */
	units: BeatFxUnitDto[],
	/**  One CFX per channel (`MVP_DECKS`). */
	cfx: CfxDto[],
	/**  Effect types the CFX selector offers. */
	cfx_kinds: EffectKey[],
	/**  `FX_SEND_BUSES` send units. */
	sends: SendUnitDto[],
	/**  Send levels `[deck][bus]`, linear `[0, 1]`. */
	send_levels: ((number | null)[])[],
	/**  `PAD_FX_COUNT` pad effects, index `bank * 16 + shift * 8 + pad`. */
	pads: PadFxAssignDto[],
};

/**  Which family of engine units a reference points at. */
export type FxTarget = 
/**  A Beat FX unit (`0..BEAT_FX_UNITS`). */
"beat" | 
/**  A send/return bus (`0..FX_SEND_BUSES`). */
"send";

/**  A Beat FX unit or a send bus. */
export type FxUnitRef = {
	/**  Family. */
	target: FxTarget,
	/**  Index inside the family. */
	unit: number,
};

/**  State of one FX unit (a chain of slots) over the last block. RT-safe. */
export type FxUnitTelemetry = {
	/**  At least one slot holding an effect is enabled. */
	enabled: boolean,
	/**
	 *  At least one slot is processing: enabled, crossfading, or ringing out
	 *  its tail after being disabled.
	 */
	active: boolean,
	/**
	 *  Peak of the unit's output over the last block it ran, linear
	 *  amplitude; 0 while idle.
	 */
	level: number | null,
};

/**
 *  A linear amplitude factor (`1.0` = unity, `0.0` = silence). Valid values
 *  are finite and `>= 0`. RT-safe.
 */
export type Gain = number | null;

/**
 *  Hot cue slot index, `0..HOT_CUES_PER_DECK` (pad 1 is index 0).
 * 
 *  Invariant enforced by [`HotCueIndex::new`] and deserialization. RT-safe.
 */
export type HotCueIndex = number;

/**  The eight hot cue slots of a deck. */
export type HotCues = {
	/**  Deck the slots belong to. */
	deck: DeckId,
	/**  One entry per slot (`HOT_CUES_PER_DECK`), `None` when empty. */
	slots: (Cue | null)[],
};

/**  A deck's hot cue slots changed (set, deleted, track loaded or ejected). */
export type HotCuesChangedEvent = HotCues;

/**  Options of an import job. */
export type ImportOptionsDto = {
	/**  Analysis to run. */
	features: AnalysisFeatures,
	/**  Playlist that receives the imported tracks. */
	target_playlist: PlaylistId | null,
};

/**  Progress of an import or analysis job, at most about 10 per second per job. */
export type ImportProgressEvent = JobProgress;

/**  An import or analysis job (`import_jobs.id`). */
export type JobId = number;

/**  A stored job for the import panel. */
export type JobInfo = {
	/**  Counts and state, shaped like the `import-progress` event payload. */
	progress: JobProgress,
	/**  Folder, playlist or XML path. */
	source: string | null,
	/**  Failure message of a failed job. */
	error: string | null,
	/**  Unix ms the job was created. */
	created_at: number,
};

/**  What started the job. */
export type JobKind = 
/**  Recursive folder import. */
"import_folder" | 
/**  Explicit list of files (drag and drop). */
"import_files" | 
/**  M3U/M3U8 playlist file. */
"import_playlist" | 
/**  rekordbox XML collection export. */
"import_rekordbox_xml" | 
/**  Re-analysis of tracks already in the library. */
"reanalyze";

/**
 *  Progress snapshot of one job, sent to the UI.
 * 
 *  Invariant: `items_done + items_failed + items_duplicate <= items_total`.
 *  `items_total` may grow while `stage == Discover`.
 */
export type JobProgress = {
	/**  Job. */
	job: JobId,
	/**  Kind. */
	kind: JobKind,
	/**  State. */
	state: JobState,
	/**  Stage of the item being processed, if any. */
	stage: JobStage | null,
	/**  Items discovered so far. */
	items_total: number,
	/**  Items done. */
	items_done: number,
	/**  Items skipped as duplicates. */
	items_duplicate: number,
	/**  Items failed. */
	items_failed: number,
	/**  Path of the item being processed, for display. */
	current_item: string | null,
	/**  Track most recently added or updated, so the UI can refresh its row. */
	last_track: TrackId | null,
};

/**  Pipeline stage of an item, in execution order. */
export type JobStage = 
/**  Walking folders or parsing the playlist/XML into items. */
"discover" | 
/**  Path and content-hash duplicate check. */
"dedupe" | 
/**  Tags and artwork. */
"tags" | 
/**  Decoding to PCM. */
"decode" | 
/**  BPM, grid, key, peaks, loudness. */
"analyze" | 
/**  Writing results to the database. */
"persist";

/**  Lifecycle state of a job. */
export type JobState = 
/**  Waiting for a worker. */
"queued" | 
/**  Processing items. */
"running" | 
/**  Paused by the user or interrupted by shutdown; resumable. */
"paused" | 
/**  Cancelled; finished items stay in the library. */
"cancelled" | 
/**  All items processed (some may have failed). */
"completed" | 
/**  The job itself failed (e.g. unreadable XML). */
"failed";

/**  Major or minor mode. */
export type KeyMode = 
/**  Major (Camelot letter B). */
"major" | 
/**  Minor (Camelot letter A). */
"minor";

/**  What a `library-changed` event says was touched. */
export type LibraryChange = {
	/**  Tracks were added, removed or edited. */
	tracks: boolean,
	/**  Playlists, folders or their entries changed. */
	playlists: boolean,
};

/**  Tracks or playlists changed (import, delete, playlist edits); coalesced. */
export type LibraryChangedEvent = LibraryChange;

/**  A loop region in seconds. Invariant: `start < end`, both finite. */
export type LoopRegion = {
	/**  Loop in point. */
	start: Seconds,
	/**  Loop out point (exclusive). */
	end: Seconds,
};

/**  Integrated loudness and true peak (EBU R128 / ITU-R BS.1770). */
export type Loudness = {
	/**  Integrated loudness, LUFS. */
	integrated_lufs: number | null,
	/**  True peak, dBTP. */
	true_peak_dbtp: number | null,
};

/**  Snapshot of the whole mixer, for the UI and session restore. */
export type MixerState = {
	/**  One strip per deck, indexed by [`DeckId::index`]. */
	channels: [ChannelState, ChannelState, ChannelState, ChannelState],
	/**  Crossfader position in `[-1, 1]`. */
	crossfader: number | null,
	/**  Crossfader curve. */
	crossfader_curve: CrossfaderCurve,
	/**  Master output level, linear. */
	master_level: Gain,
	/**  Headphone output level, linear. */
	headphone_level: Gain,
	/**  Headphone mix in `[0, 1]`: 0 = cue only, 1 = master only. */
	headphone_mix: number | null,
	/**  Split cue: cue bus summed to mono on the left ear, master mono on the right. */
	split_cue: boolean,
};

/**
 *  A musical key: tonic pitch class plus mode. RT-safe.
 * 
 *  Invariant: `tonic < 12`, where 0 = C, 1 = C#/Db, ..., 11 = B. Build with
 *  [`MusicalKey::new`] or a parser. Serialized as the Camelot string (`"8A"`),
 *  which is also the format stored in the library.
 */
export type MusicalKey = string;

/**  What a pad does when held. */
export type PadFxAssignDto = {
	/**  Effect, `None` for an empty pad. */
	effect: EffectKey | null,
	/**  Beat division in beats. */
	division: number | null,
	/**  Release FX pad: press fires the release effect instead of holding it. */
	release: boolean,
};

/**  One of the eight pad modes. RT-safe (plain enum). */
export type PadMode = 
/**  Pads trigger or set hot cues 1-8 (button 5-1). */
"hot_cue" | 
/**  Pads trigger pad effects, bank 1 (button 5-2). */
"pad_fx1" | 
/**  Pads jump by fixed beat counts (button 5-3). */
"beat_jump" | 
/**  Pads trigger sampler slots (button 5-4). */
"sampler" | 
/**  Pads play the hot cue chromatically (SHIFT + 5-1). */
"keyboard" | 
/**  Pads trigger pad effects, bank 2 (SHIFT + 5-2). */
"pad_fx2" | 
/**  Pads set auto beat loops (SHIFT + 5-3). */
"beat_loop" | 
/**  Pads shift the key by semitones (SHIFT + 5-4). */
"key_shift";

/**  How a normalized `[0, 1]` value maps to the plain range. */
export type ParamCurve = 
/**  `plain = min + n * (max - min)`. */
{ kind: "linear" } | 
/**  `plain = min * (max / min)^n`. Requires `min > 0` (frequencies, times). */
{ kind: "logarithmic" } | 
/**
 *  `steps` evenly spaced values from `min` to `max`, `steps >= 2`
 *  (switches, beat divisions).
 */
{ kind: "stepped"; 
/**  Number of distinct values. */
steps: number };

/**
 *  Static description of one parameter. Built on the control thread.
 * 
 *  Invariants: `min < max`; `min <= default <= max`; for `Logarithmic`,
 *  `min > 0`; for `Stepped`, `steps >= 2`. Values crossing the engine
 *  boundary are normalized `[0, 1]`; [`ParamDescriptor::to_plain`] and
 *  [`ParamDescriptor::to_normalized`] convert, RT-safe.
 */
export type ParamDescriptor = {
	/**  Stable id. */
	id: ParamId,
	/**  Display name. */
	name: string,
	/**  Display unit. */
	unit: ParamUnit,
	/**  Lowest plain value. */
	min: number | null,
	/**  Highest plain value. */
	max: number | null,
	/**  Default plain value. */
	default: number | null,
	/**  Mapping from normalized to plain. */
	curve: ParamCurve,
};

/**
 *  Parameter identifier, unique within one effect. Stable across versions of
 *  that effect because presets store it. `u32` to fit CLAP and VST3 ids.
 */
export type ParamId = number;

/**  Unit shown next to a parameter value. */
export type ParamUnit = 
/**  Plain number. */
"none" | 
/**  Percent, 0..100. */
"percent" | 
/**  Decibels. */
"decibels" | 
/**  Hertz. */
"hertz" | 
/**  Milliseconds. */
"milliseconds" | 
/**  Beats (beat-synced time). */
"beats" | 
/**  Semitones. */
"semitones";

/**
 *  Raw peak blob (`contracts::peaks` v1). A binary payload on the wire, typed
 *  `number[]` in the bindings like [`ArtworkBytes`]; the UI decodes it from an
 *  `ArrayBuffer` in `ui/src/viz/peaks.ts`.
 */
export type PeakBytes = number[];

/**  Transport state of a deck. */
export type PlayState = 
/**  No track loaded. */
"empty" | 
/**  Track is being decoded by the loader thread. */
"loading" | 
/**  Loaded and stopped. */
"paused" | 
/**  Playing. */
"playing" | 
/**  CUE held while paused: playing from the cue point until release. */
"cue_preview";

